// Cold-start / outage protection for the first screen. Wraps fetch for the three first-screen GETs only:
// if the live call fails (network error or HTTP 5xx), answer from /static/snapshot.json and show a banner.
// Everything else (chat, rulebook, import) still fails honestly. Generated by scripts/make_snapshot.py.
(function () {
  var real = window.fetch.bind(window), snap = null, shown = false;
  function load() {
    if (!snap) snap = real("/static/snapshot.json").then(function (r) { if (!r.ok) throw new Error("no snapshot"); return r.json(); });
    return snap;
  }
  function banner(date) {
    if (shown) return; shown = true;
    var d = document.createElement("div");
    d.id = "snapbanner"; d.setAttribute("role", "status");
    d.style.cssText = "background:var(--warn-soft,#f6e6c8);color:var(--warn,#9a5b00);border-bottom:1px solid var(--line,#d9d5ca);padding:8px 16px;font-size:13.5px;text-align:center";
    d.textContent = "Live server unreachable, showing snapshot from " + date + ". Numbers below are saved, not live.";
    document.body.insertBefore(d, document.body.firstChild);
  }
  function from(s, path, qs) {
    var m, body = null;
    if (path === "/api/traders") body = s.traders;
    else if ((m = path.match(/^\/api\/review\/([^\/]+)$/))) body = s.review[decodeURIComponent(m[1])];
    else if ((m = path.match(/^\/api\/toggle\/([^\/]+)$/))) body = s.toggle[decodeURIComponent(m[1]) + "|" + (new URLSearchParams(qs).get("rule") || "halt")];
    return body ? new Response(JSON.stringify(body), { status: 200, headers: { "Content-Type": "application/json" } }) : null;
  }
  window.fetch = function (input, init) {
    var url = typeof input === "string" ? input : (input && input.url) || "";
    var u; try { u = new URL(url, location.href); } catch (e) { return real(input, init); }
    var method = ((init && init.method) || (input && input.method) || "GET").toUpperCase();
    if (u.origin !== location.origin || method !== "GET" || !/^\/api\/(traders|review\/|toggle\/)/.test(u.pathname)) return real(input, init);
    function fallback(r, err) {
      return load().then(function (s) {
        var out = from(s, u.pathname, u.search);
        if (!out) { if (r) return r; throw err; }
        banner(s.generated);
        return out;
      }, function () { if (r) return r; throw err; });
    }
    return real(input, init).then(function (r) { return r.status < 500 ? r : fallback(r); }, function (err) { return fallback(null, err); });
  };
})();
